-- FLUX Workout Editor V2, Slice 2G.
--
-- Initial Russian exercise catalog. This is an operational seed, not a
-- migration: run it explicitly through a privileged maintenance connection.
-- It is safe to re-run. Existing rows with the same slug are never updated,
-- and link rows/aliases are created only for catalog rows inserted by this run.
-- No user-owned exercise, plan, session, or catalog row is deleted or changed.

begin;

create temporary table flux_catalog_seed (
  slug text primary key,
  name text not null,
  measurement_type text not null,
  primary_muscle_slug text not null,
  secondary_muscle_slugs text[] not null,
  equipment_slugs text[] not null,
  aliases text[] not null,
  technique_description text not null
) on commit drop;

create temporary table flux_catalog_inserted (
  slug text primary key,
  id uuid not null
) on commit drop;

