insert into flux_catalog_seed (
  slug, name, measurement_type, primary_muscle_slug, secondary_muscle_slugs,
  equipment_slugs, aliases, technique_description
) values
  -- Грудь (12)
  ('barbell-bench-press', 'Жим штанги лёжа', 'reps', 'chest', array['triceps','shoulders'], array['barbell','bench'], array['жим лежа','bench press'], 'Исходное положение: лягте на скамью, стопы устойчиво на полу. Выполнение: опустите штангу к середине груди и выжмите вверх. Контроль: держите лопатки сведёнными и запястья над локтями. Ошибки: отрыв таза, отбив штанги от груди и чрезмерный прогиб поясницы.'),
  ('incline-barbell-bench-press', 'Жим штанги на наклонной скамье', 'reps', 'chest', array['triceps','shoulders'], array['barbell','bench'], array['наклонный жим штанги','incline bench press'], 'Исходное положение: лягте на наклонную скамью, стопы поставьте устойчиво. Выполнение: опустите штангу к верхней части груди и выжмите по дуге. Контроль: сведите лопатки и сохраняйте ровные запястья. Ошибки: поднимать плечи к ушам, терять опору стоп и резко опускать штангу.'),
  ('dumbbell-bench-press', 'Жим гантелей лёжа', 'reps', 'chest', array['triceps','shoulders'], array['dumbbells','bench'], array['жим гантелей','dumbbell press'], 'Исходное положение: лягте на скамью, гантели над плечами. Выполнение: опускайте локти под контролем и сведите гантели вверх. Контроль: удерживайте лопатки на скамье и двигайтесь симметрично. Ошибки: сталкивать гантели, разводить локти слишком широко и терять нейтральные запястья.'),
  ('incline-dumbbell-bench-press', 'Жим гантелей на наклонной скамье', 'reps', 'chest', array['triceps','shoulders'], array['dumbbells','bench'], array['наклонный жим гантелей','incline dumbbell press'], 'Исходное положение: сядьте на наклонную скамью и поднимите гантели к плечам. Выполнение: выжмите гантели вверх и плавно верните. Контроль: лопатки остаются сведёнными, стопы не скользят. Ошибки: прогибать поясницу, опускать гантели рывком и сводить плечи вперёд.'),
  ('dumbbell-fly', 'Разводка с гантелями лёжа', 'reps', 'chest', array['shoulders'], array['dumbbells','bench'], array['разводка гантелей','dumbbell fly'], 'Исходное положение: лягте на скамью, гантели держите над грудью с мягкими локтями. Выполнение: разведите руки по широкой дуге и сведите обратно. Контроль: сохраняйте одинаковый угол в локтях. Ошибки: глубоко опускать плечи, полностью выпрямлять локти и использовать инерцию.'),
  ('cable-fly', 'Сведение рук в кроссовере', 'reps', 'chest', array['shoulders'], array['cable-machine'], array['кроссовер на грудь','cable fly'], 'Исходное положение: встаньте между блоками, корпус слегка наклоните вперёд. Выполнение: сведите рукояти перед грудью по дуге. Контроль: плечи опущены, корпус неподвижен. Ошибки: тянуть руками за спиной, округлять поясницу и раскачиваться.'),
  ('push-up', 'Отжимания от пола', 'reps', 'chest', array['triceps','shoulders','core'], array['bodyweight'], array['отжимание','push-up'], 'Исходное положение: примите упор лёжа, ладони под плечами, тело в прямой линии. Выполнение: опустите грудь к полу и выжмите себя вверх. Контроль: напрягайте корпус и держите локти под удобным углом. Ошибки: провисать в пояснице, поднимать таз и сокращать амплитуду.'),
  ('wide-push-up', 'Отжимания широким хватом', 'reps', 'chest', array['shoulders','core'], array['bodyweight'], array['широкие отжимания','wide push-up'], 'Исходное положение: примите упор лёжа с ладонями шире плеч. Выполнение: опустите грудь к полу и вернитесь в упор. Контроль: сохраняйте прямую линию тела и стабильные лопатки. Ошибки: чрезмерно разводить локти, провисать в пояснице и выполнять рывками.'),
  ('chest-dip', 'Отжимания на брусьях с акцентом на грудь', 'reps', 'chest', array['triceps','shoulders'], array['dip-bars'], array['брусья на грудь','chest dip'], 'Исходное положение: удерживайтесь на брусьях, корпус слегка наклоните вперёд. Выполнение: опуститесь до комфортной глубины и выжмите себя вверх. Контроль: лопатки стабильны, движение плавное. Ошибки: резко проваливаться вниз, раскачиваться и поднимать плечи к ушам.'),
  ('machine-chest-press', 'Жим от груди в тренажёре', 'reps', 'chest', array['triceps','shoulders'], array['chest-press-machine'], array['жим в тренажере','machine chest press'], 'Исходное положение: сядьте так, чтобы рукояти были на уровне середины груди. Выполнение: выжмите рукояти вперёд и медленно верните. Контроль: прижмите спину к опоре и держите плечи опущенными. Ошибки: блокировать локти, отрывать спину и сокращать возврат.'),
  ('smith-incline-press', 'Жим в Смите на наклонной скамье', 'reps', 'chest', array['triceps','shoulders'], array['smith-machine','bench'], array['наклонный жим в смите','smith incline press'], 'Исходное положение: разместите скамью в Смите, гриф над верхней частью груди. Выполнение: опустите гриф контролируемо и выжмите вверх. Контроль: сведите лопатки и держите стопы на полу. Ошибки: ставить скамью слишком близко к грифу, терять контроль и запирать локти.'),
  ('resistance-band-chest-press', 'Жим от груди с резинкой', 'reps', 'chest', array['triceps','shoulders'], array['resistance-band'], array['жим с резинкой на грудь','band chest press'], 'Исходное положение: закрепите резинку за спиной и встаньте устойчиво. Выполнение: выжмите руки вперёд и верните с контролем. Контроль: корпус остаётся неподвижным, плечи опущены. Ошибки: терять натяжение, разворачивать корпус и выпрямлять локти рывком.'),

  -- Спина (16)
  ('conventional-deadlift', 'Становая тяга', 'reps', 'back', array['glutes','hamstrings','lower-back'], array['barbell'], array['становая','deadlift'], 'Исходное положение: встаньте у грифа, стопы под ним, спина нейтральна. Выполнение: оттолкнитесь ногами и выпрямитесь с грифом близко к телу. Контроль: напрягайте корпус и сохраняйте штангу у ног. Ошибки: округлять спину, дёргать гриф и уводить его вперёд.'),
  ('pull-up', 'Подтягивания прямым хватом', 'reps', 'back', array['biceps','forearms'], array['pull-up-bar'], array['подтягивания','pull-up','pull up'], 'Исходное положение: повисните на турнике с активными плечами. Выполнение: подтяните грудь к перекладине и опуститесь под контролем. Контроль: не раскачивайтесь, ведите локти вниз. Ошибки: рывок ногами, запрокидывание шеи и неполное опускание.'),
  ('chin-up', 'Подтягивания обратным хватом', 'reps', 'back', array['biceps','forearms'], array['pull-up-bar'], array['подтягивания обратным хватом','chin-up'], 'Исходное положение: повисните на перекладине хватом снизу, плечи активны. Выполнение: подтянитесь до уровня подбородка и опуститесь плавно. Контроль: удерживайте корпус без раскачки. Ошибки: дёргать корпусом, поднимать плечи и резко падать вниз.'),
  ('lat-pulldown', 'Тяга верхнего блока к груди', 'reps', 'back', array['biceps','forearms'], array['lat-pulldown-machine'], array['верхняя тяга','lat pulldown'], 'Исходное положение: сядьте устойчиво, зафиксируйте бёдра валиком. Выполнение: тяните рукоять к верхней части груди и плавно отпускайте. Контроль: ведите локти вниз, грудь слегка поднята. Ошибки: тянуть за голову, раскачивать корпус и поднимать плечи.'),
  ('close-grip-lat-pulldown', 'Тяга верхнего блока узким хватом', 'reps', 'back', array['biceps','forearms'], array['lat-pulldown-machine'], array['узкая верхняя тяга','close grip lat pulldown'], 'Исходное положение: сядьте у верхнего блока и возьмите узкую рукоять. Выполнение: тяните её к груди, затем контролируемо верните. Контроль: локти идут вниз вдоль корпуса, спина не раскачивается. Ошибки: отклоняться назад, тянуть кистями и бросать вес.'),
  ('barbell-bent-over-row', 'Тяга штанги в наклоне', 'reps', 'back', array['biceps','lower-back'], array['barbell'], array['тяга штанги к поясу','barbell row'], 'Исходное положение: наклонитесь с нейтральной спиной, гриф держите у колен. Выполнение: подтяните штангу к низу живота и опустите. Контроль: корпус стабилен, локти идут назад. Ошибки: округлять поясницу, выпрямляться на каждом повторе и дёргать вес.'),
  ('pendlay-row', 'Тяга Пендлея', 'reps', 'back', array['biceps','lower-back'], array['barbell'], array['pendlay row','тяга с пола в наклоне'], 'Исходное положение: наклонитесь над грифом на полу, спина нейтральна. Выполнение: подтяните гриф к животу и каждый раз верните на пол. Контроль: сохраняйте жёсткий корпус. Ошибки: округлять спину, поднимать плечи и отрывать гриф рывком.'),
  ('one-arm-dumbbell-row', 'Тяга гантели одной рукой', 'reps', 'back', array['biceps'], array['dumbbells','bench'], array['тяга гантели в наклоне','one arm dumbbell row'], 'Исходное положение: упритесь рукой и коленом в скамью, спина ровная. Выполнение: тяните гантель к тазу и опускайте. Контроль: плечо не разворачивается вперёд. Ошибки: скручивать корпус, тянуть к груди и раскачивать гантель.'),
  ('chest-supported-dumbbell-row', 'Тяга гантелей с опорой грудью', 'reps', 'back', array['biceps'], array['dumbbells','bench'], array['тяга с упором грудью','chest supported row'], 'Исходное положение: лягте грудью на наклонную скамью, руки с гантелями вниз. Выполнение: тяните локти назад и опускайте гантели. Контроль: грудь остаётся на опоре. Ошибки: отрывать грудь, поднимать плечи и сокращать амплитуду.'),
  ('seated-cable-row', 'Тяга горизонтального блока сидя', 'reps', 'back', array['biceps'], array['cable-machine'], array['горизонтальная тяга','seated cable row'], 'Исходное положение: сядьте ровно, возьмите рукоять и слегка согните колени. Выполнение: тяните рукоять к животу и верните. Контроль: плечи опущены, корпус не раскачивается. Ошибки: округлять спину, отклоняться назад и дёргать рукоять.'),
  ('t-bar-row', 'Тяга Т-грифа', 'reps', 'back', array['biceps','lower-back'], array['t-bar-machine'], array['т тяга','t-bar row'], 'Исходное положение: встаньте на платформу Т-тренажёра, корпус наклонён и стабилен. Выполнение: тяните рукояти к животу. Контроль: ведите локти назад и не меняйте угол корпуса. Ошибки: округлять спину, раскачиваться и поднимать плечи.'),
  ('machine-row', 'Тяга в тренажёре сидя', 'reps', 'back', array['biceps'], array['row-machine'], array['тяга в тренажере','machine row'], 'Исходное положение: сядьте с опорой грудью или спиной согласно тренажёру. Выполнение: тяните рукояти к корпусу и плавно верните. Контроль: лопатки двигаются без подъёма плеч. Ошибки: рывки, отрыв от опоры и слишком короткая амплитуда.'),
  ('straight-arm-pulldown', 'Пуловер на верхнем блоке', 'reps', 'back', array['triceps','core'], array['cable-machine'], array['тяга прямыми руками','straight arm pulldown'], 'Исходное положение: встаньте лицом к верхнему блоку, руки почти прямые. Выполнение: опустите рукоять к бёдрам и верните. Контроль: корпус стабилен, плечи не поднимаются. Ошибки: сгибать локти, раскачиваться и прогибаться в пояснице.'),
  ('hyperextension', 'Гиперэкстензия', 'reps', 'lower-back', array['glutes','hamstrings'], array['bodyweight'], array['разгибание спины','back extension'], 'Исходное положение: закрепите ноги, корпус опустите с нейтральной спиной. Выполнение: поднимитесь до прямой линии с ногами. Контроль: движение идёт в тазобедренных суставах. Ошибки: переразгибать поясницу, запрокидывать голову и делать рывок.'),
  ('inverted-row', 'Австралийские подтягивания', 'reps', 'back', array['biceps','core'], array['barbell'], array['горизонтальные подтягивания','inverted row'], 'Исходное положение: лягте под низко установленный гриф, тело держите прямым. Выполнение: подтяните грудь к грифу и опуститесь. Контроль: напрягайте ягодицы и корпус. Ошибки: провисать тазом, тянуть шеей и раскачиваться.'),
  ('good-morning', 'Наклоны со штангой на плечах', 'reps', 'back', array['hamstrings','glutes'], array['barbell'], array['good morning','наклоны со штангой'], 'Исходное положение: положите лёгкую штангу на верх спины, колени мягкие. Выполнение: отведите таз назад, наклонитесь и вернитесь. Контроль: спина нейтральна, движение в тазобедренных суставах. Ошибки: округляться, сгибать колени слишком сильно и опускаться рывком.'),

  -- Плечи (11)
  ('standing-barbell-press', 'Жим штанги стоя', 'reps', 'shoulders', array['triceps','core'], array['barbell'], array['армейский жим','overhead press'], 'Исходное положение: встаньте ровно, гриф у верхней части груди. Выполнение: выжмите штангу над головой и верните. Контроль: напрягайте ягодицы и корпус, путь грифа близок к лицу. Ошибки: сильный прогиб поясницы, толчок ногами и запрокидывание головы.'),
  ('seated-dumbbell-press', 'Жим гантелей сидя', 'reps', 'shoulders', array['triceps'], array['dumbbells','bench'], array['жим гантелей сидя','seated dumbbell press'], 'Исходное положение: сядьте с опорой спины, гантели у плеч. Выполнение: выжмите их вверх и плавно опустите. Контроль: поясница на опоре, предплечья вертикальны. Ошибки: сталкивать гантели, выгибать спину и поднимать плечи.'),
  ('arnold-press', 'Жим Арнольда', 'reps', 'shoulders', array['triceps'], array['dumbbells','bench'], array['arnold press','жим арнольда'], 'Исходное положение: сядьте, гантели перед лицом ладонями к себе. Выполнение: одновременно разверните ладони и выжмите вверх. Контроль: двигайтесь плавно без потери опоры. Ошибки: чрезмерно вращать плечо, выгибать поясницу и спешить.'),
  ('dumbbell-lateral-raise', 'Разведение гантелей в стороны', 'reps', 'shoulders', array[]::text[], array['dumbbells'], array['махи гантелями в стороны','dumbbell lateral raise'], 'Исходное положение: встаньте с гантелями по бокам, локти слегка согнуты. Выполнение: поднимите руки в стороны до уровня плеч и опустите. Контроль: корпус неподвижен, плечи опущены. Ошибки: раскачиваться, поднимать гантели выше комфортного уровня и пожимать плечами.'),
  ('cable-lateral-raise', 'Разведение руки в сторону на нижнем блоке', 'reps', 'shoulders', array[]::text[], array['cable-machine'], array['махи на блоке','cable lateral raise'], 'Исходное положение: встаньте боком к нижнему блоку и возьмите рукоять дальней рукой. Выполнение: поднимите руку в сторону и медленно верните. Контроль: локоть мягкий, корпус не наклоняется. Ошибки: раскачка, подъём плеча и рывок из нижней точки.'),
  ('dumbbell-front-raise', 'Подъём гантелей перед собой', 'reps', 'shoulders', array['chest'], array['dumbbells'], array['махи гантелями перед собой','dumbbell front raise'], 'Исходное положение: встаньте, гантели перед бёдрами, колени мягкие. Выполнение: поднимите руки перед собой до уровня плеч и опустите. Контроль: корпус устойчив. Ошибки: раскачиваться, запрокидывать корпус и поднимать плечи.'),
  ('reverse-dumbbell-fly', 'Разведение гантелей в наклоне', 'reps', 'shoulders', array['back'], array['dumbbells'], array['обратная разводка','reverse fly'], 'Исходное положение: наклонитесь с ровной спиной, гантели под плечами. Выполнение: разведите руки в стороны и верните. Контроль: шея расслаблена, лопатки двигаются плавно. Ошибки: тянуть трапециями, раскачивать корпус и разгибать поясницу.'),
  ('rear-delt-machine', 'Разведение в тренажёре на заднюю дельту', 'reps', 'shoulders', array['back'], array['chest-press-machine'], array['задняя дельта в тренажере','rear delt machine'], 'Исходное положение: сядьте лицом к опоре и возьмите рукояти. Выполнение: разведите руки назад и плавно верните. Контроль: грудь на опоре, плечи опущены. Ошибки: рывки, прогиб в пояснице и слишком большой вес.'),
  ('upright-row-cable', 'Тяга нижнего блока к подбородку', 'reps', 'shoulders', array['trapezius'], array['cable-machine'], array['тяга к подбородку','upright row'], 'Исходное положение: встаньте у нижнего блока, рукоять перед бёдрами. Выполнение: тяните её вдоль тела до комфортной высоты. Контроль: локти не уходят болезненно высоко, плечи опущены. Ошибки: рывок, чрезмерный подъём локтей и раскачка корпуса.'),
  ('face-pull', 'Тяга каната к лицу', 'reps', 'shoulders', array['back'], array['cable-machine'], array['face pull','фейс пул'], 'Исходное положение: встаньте лицом к верхнему блоку, возьмите канат. Выполнение: тяните концы каната к лицу, разводя их в стороны. Контроль: локти идут в стороны, плечи не поднимаются. Ошибки: отклоняться назад, тянуть поясницей и сводить плечи вперёд.'),
  ('pike-push-up', 'Отжимания уголком', 'reps', 'shoulders', array['triceps','core'], array['bodyweight'], array['pike push-up','отжимания домиком'], 'Исходное положение: примите упор с тазом высоко, ладони на ширине плеч. Выполнение: опустите макушку к полу между ладонями и выжмите себя. Контроль: переносите вес на руки плавно. Ошибки: провисать в пояснице, ставить голову слишком далеко и делать рывок.'),

  -- Руки (18)
  ('barbell-curl', 'Сгибание рук со штангой', 'reps', 'biceps', array['forearms'], array['barbell'], array['подъем штанги на бицепс','barbell curl'], 'Исходное положение: встаньте ровно, гриф держите перед бёдрами. Выполнение: согните руки до уровня плеч и опустите. Контроль: локти остаются у корпуса. Ошибки: раскачивать спину, выводить локти вперёд и бросать гриф вниз.'),
  ('dumbbell-curl', 'Сгибание рук с гантелями стоя', 'reps', 'biceps', array['forearms'], array['dumbbells'], array['подъем гантелей на бицепс','dumbbell curl'], 'Исходное положение: встаньте с гантелями по бокам, ладони вперёд. Выполнение: согните руки и медленно опустите. Контроль: плечи неподвижны, локти у корпуса. Ошибки: раскачка, подъём локтей и резкое опускание.'),
  ('hammer-curl', 'Молотковые сгибания с гантелями', 'reps', 'biceps', array['forearms'], array['dumbbells'], array['молотки','hammer curl'], 'Исходное положение: держите гантели нейтральным хватом вдоль тела. Выполнение: согните руки без разворота кистей и опустите. Контроль: локти фиксированы около корпуса. Ошибки: раскачиваться, сводить плечи вперёд и терять положение кистей.'),
  ('incline-dumbbell-curl', 'Сгибание гантелей на наклонной скамье', 'reps', 'biceps', array['forearms'], array['dumbbells','bench'], array['наклонные сгибания','incline dumbbell curl'], 'Исходное положение: сядьте на наклонную скамью, руки свободно опущены. Выполнение: согните руки к плечам и контролируемо опустите. Контроль: плечи остаются у спинки. Ошибки: выводить локти вперёд, раскачивать корпус и бросать гантели.'),
  ('concentration-curl', 'Концентрированное сгибание с гантелью', 'reps', 'biceps', array['forearms'], array['dumbbells','bench'], array['концентрированный подъем','concentration curl'], 'Исходное положение: сядьте, локоть рабочей руки уприте во внутреннюю сторону бедра. Выполнение: согните руку и опустите гантель. Контроль: плечо не двигается, спина нейтральна. Ошибки: помогать корпусом, отрывать локоть и выполнять слишком быстро.'),
  ('cable-curl', 'Сгибание рук на нижнем блоке', 'reps', 'biceps', array['forearms'], array['cable-machine'], array['сгибание на блоке','cable curl'], 'Исходное положение: встаньте у нижнего блока, локти прижаты к корпусу. Выполнение: согните руки к плечам и медленно верните рукоять. Контроль: корпус неподвижен. Ошибки: отклоняться назад, поднимать локти и бросать вес.'),
  ('preacher-curl-machine', 'Сгибание рук в тренажёре Скотта', 'reps', 'biceps', array['forearms'], array['row-machine'], array['скамья скотта','preacher curl'], 'Исходное положение: сядьте в тренажёр, плечи и локти на опоре. Выполнение: согните руки до комфортной точки и медленно опустите. Контроль: не отрывайте плечи от подушки. Ошибки: разгибать локти до упора, делать рывок и поднимать плечи.'),
  ('reverse-barbell-curl', 'Обратное сгибание рук со штангой', 'reps', 'forearms', array['biceps'], array['barbell'], array['обратный подъем штанги','reverse curl'], 'Исходное положение: держите гриф хватом сверху перед бёдрами. Выполнение: согните руки и плавно опустите. Контроль: локти у корпуса, запястья ровные. Ошибки: раскачивать корпус, заламывать кисти и опускать гриф рывком.'),
  ('triceps-pushdown', 'Разгибание рук на верхнем блоке', 'reps', 'triceps', array[]::text[], array['cable-machine'], array['разгибание на блоке','triceps pushdown'], 'Исходное положение: встаньте у верхнего блока, локти прижмите к корпусу. Выполнение: разогните руки вниз и верните рукоять. Контроль: плечи не двигаются, корпус устойчив. Ошибки: наклоняться всем телом, разводить локти и бросать вес.'),
  ('rope-triceps-pushdown', 'Разгибание рук с канатом', 'reps', 'triceps', array[]::text[], array['cable-machine'], array['канат на трицепс','rope pushdown'], 'Исходное положение: возьмите канат на верхнем блоке, локти рядом с корпусом. Выполнение: разогните руки и слегка разведите концы внизу. Контроль: запястья нейтральны, плечи опущены. Ошибки: помогать спиной, поднимать локти и резко возвращать вес.'),
  ('overhead-cable-triceps-extension', 'Разгибание рук из-за головы на блоке', 'reps', 'triceps', array['core'], array['cable-machine'], array['французское разгибание на блоке','overhead cable extension'], 'Исходное положение: повернитесь спиной к блоку, рукоять за головой. Выполнение: разогните руки вверх и верните. Контроль: локти направлены вперёд, корпус устойчив. Ошибки: прогибать поясницу, разводить локти и тянуть шеей.'),
  ('overhead-dumbbell-triceps-extension', 'Разгибание гантели из-за головы', 'reps', 'triceps', array[]::text[], array['dumbbells'], array['французский жим с гантелью','overhead dumbbell extension'], 'Исходное положение: держите одну гантель над головой обеими руками. Выполнение: опустите её за голову и разогните руки. Контроль: локти смотрят вперёд, корпус не прогибается. Ошибки: разводить локти, торопиться и перегружать поясницу.'),
  ('skull-crusher', 'Французский жим лёжа', 'reps', 'triceps', array[]::text[], array['barbell','bench'], array['разгибание рук лежа','skull crusher'], 'Исходное положение: лягте на скамью, гриф держите над плечами. Выполнение: согните локти, опустите гриф к области за головой и разогните. Контроль: плечи неподвижны. Ошибки: опускать гриф рывком, разводить локти и уводить плечи назад.'),
  ('close-grip-bench-press', 'Жим штанги лёжа узким хватом', 'reps', 'triceps', array['chest','shoulders'], array['barbell','bench'], array['узкий жим','close grip bench press'], 'Исходное положение: лягте на скамью, возьмите гриф немного уже плеч. Выполнение: опустите его к груди и выжмите вверх. Контроль: локти идут близко к корпусу, лопатки стабильны. Ошибки: слишком узкий хват, отрыв таза и отбив штанги.'),
  ('bench-dip', 'Обратные отжимания от скамьи', 'reps', 'triceps', array['shoulders'], array['bench','bodyweight'], array['отжимания от скамьи','bench dip'], 'Исходное положение: упритесь ладонями в край скамьи, ноги впереди. Выполнение: согните локти до комфортной глубины и выжмите себя. Контроль: спина близко к скамье, плечи опущены. Ошибки: уходить слишком глубоко, сутулиться и делать рывки.'),
  ('triceps-extension-machine', 'Разгибание рук в тренажёре', 'reps', 'triceps', array[]::text[], array['row-machine'], array['трицепс в тренажере','triceps extension machine'], 'Исходное положение: настройте сиденье так, чтобы локти совпали с осью тренажёра. Выполнение: разогните руки и плавно верните. Контроль: плечи не поднимаются. Ошибки: сдвигаться на сиденье, блокировать локти и бросать вес.'),
  ('wrist-curl', 'Сгибание кистей с гантелями', 'reps', 'forearms', array[]::text[], array['dumbbells','bench'], array['сгибание кистей','wrist curl'], 'Исходное положение: сядьте, предплечья положите на бёдра или скамью, кисти свисают. Выполнение: согните кисти и медленно опустите. Контроль: предплечья остаются на опоре. Ошибки: двигать локтями, делать рывки и перегружать запястья.'),
  ('reverse-wrist-curl', 'Разгибание кистей с гантелями', 'reps', 'forearms', array[]::text[], array['dumbbells','bench'], array['разгибание кистей','reverse wrist curl'], 'Исходное положение: положите предплечья на опору, ладони направьте вниз. Выполнение: поднимите тыльную сторону кистей и верните. Контроль: движение только в кистях. Ошибки: помогать предплечьем, использовать инерцию и заламывать запястья.'),

  -- Ноги и ягодицы (25)
  ('barbell-back-squat', 'Приседания со штангой на спине', 'reps', 'quadriceps', array['glutes','hamstrings','core'], array['barbell'], array['присед со штангой','back squat'], 'Исходное положение: разместите гриф на верхней части спины, стопы устойчиво. Выполнение: сядьте тазом вниз и встаньте, отталкиваясь стопами. Контроль: колени следуют за носками, спина нейтральна. Ошибки: сводить колени, округлять поясницу и отрывать пятки.'),
  ('front-squat', 'Фронтальные приседания', 'reps', 'quadriceps', array['glutes','core'], array['barbell'], array['фронтальный присед','front squat'], 'Исходное положение: расположите гриф на передней части плеч, локти высоко. Выполнение: опуститесь в присед и поднимитесь. Контроль: корпус остаётся вертикальным, стопы на полу. Ошибки: опускать локти, сводить колени и терять нейтральную спину.'),
  ('goblet-squat', 'Приседания с гантелью у груди', 'reps', 'quadriceps', array['glutes','core'], array['dumbbells'], array['гоблет присед','goblet squat'], 'Исходное положение: держите гантель вертикально у груди, стопы устойчивы. Выполнение: сядьте между бёдрами и встаньте. Контроль: грудь открыта, колени направлены по носкам. Ошибки: округлять спину, отрывать пятки и опускать гантель от груди.'),
  ('smith-squat', 'Приседания в Смите', 'reps', 'quadriceps', array['glutes'], array['smith-machine'], array['присед в смите','smith squat'], 'Исходное положение: встаньте под грифом Смита, стопы поставьте устойчиво. Выполнение: опуститесь в присед и выпрямитесь. Контроль: колени идут по линии носков, спина у опоры траектории. Ошибки: ставить стопы слишком близко, отрывать пятки и резко менять темп.'),
  ('leg-press', 'Жим ногами в тренажёре', 'reps', 'quadriceps', array['glutes','hamstrings'], array['leg-press-machine'], array['жим ногами','leg press'], 'Исходное положение: сядьте в тренажёр, стопы на платформе на ширине плеч. Выполнение: опустите платформу до комфортной глубины и выжмите. Контроль: поясница остаётся на спинке, колени направлены по носкам. Ошибки: отрывать таз, выпрямлять колени до упора и опускать платформу рывком.'),
  ('hack-squat', 'Гакк-приседания в тренажёре', 'reps', 'quadriceps', array['glutes'], array['hack-squat-machine'], array['гакк присед','hack squat'], 'Исходное положение: расположитесь в тренажёре, спина и плечи на опорах. Выполнение: опуститесь, сгибая колени, и выжмите платформу. Контроль: пятки прижаты, колени идут по носкам. Ошибки: отрывать пятки, блокировать колени и сокращать амплитуду.'),
  ('bulgarian-split-squat', 'Болгарские выпады', 'reps', 'quadriceps', array['glutes','hamstrings'], array['dumbbells','bench'], array['болгарский сплит присед','bulgarian split squat'], 'Исходное положение: заднюю стопу поставьте на скамью, передняя нога устойчива. Выполнение: опуститесь вниз и вернитесь через переднюю стопу. Контроль: таз смотрит вперёд, колено следует за носком. Ошибки: заваливаться вперёд, терять равновесие и отталкиваться задней ногой.'),
  ('walking-lunge', 'Выпады в ходьбе', 'reps', 'quadriceps', array['glutes','hamstrings'], array['dumbbells'], array['шагающие выпады','walking lunge'], 'Исходное положение: встаньте ровно, при необходимости держите гантели по бокам. Выполнение: шагните вперёд, опуститесь и перейдите в следующий шаг. Контроль: корпус вертикален, колено следует за носком. Ошибки: делать слишком короткий шаг, заваливать колено внутрь и терять баланс.'),
  ('reverse-lunge', 'Обратные выпады', 'reps', 'quadriceps', array['glutes','hamstrings'], array['dumbbells'], array['выпады назад','reverse lunge'], 'Исходное положение: встаньте ровно, стопы на ширине таза. Выполнение: шагните назад, опустите колено и вернитесь в стойку. Контроль: вес на передней стопе, корпус устойчив. Ошибки: падать назад, сводить переднее колено и отталкиваться носком.'),
  ('step-up', 'Зашагивания на тумбу', 'reps', 'quadriceps', array['glutes','hamstrings'], array['plyo-box','dumbbells'], array['зашагивания','step-up'], 'Исходное положение: встаньте перед устойчивой тумбой, поставьте всю стопу сверху. Выполнение: поднимитесь через опорную ногу и контролируемо спуститесь. Контроль: колено опорной ноги стабильно. Ошибки: отталкиваться нижней ногой, ставить носок на край и падать вниз.'),
  ('leg-extension', 'Разгибание ног в тренажёре', 'reps', 'quadriceps', array[]::text[], array['leg-extension-machine'], array['разгибание ног','leg extension'], 'Исходное положение: сядьте, валик расположен над голенями, спина на опоре. Выполнение: разогните колени и плавно верните валик. Контроль: таз не сдвигается, движение спокойное. Ошибки: бросать вес, резко блокировать колени и отрываться от сиденья.'),
  ('lying-leg-curl', 'Сгибание ног лёжа в тренажёре', 'reps', 'hamstrings', array['calves'], array['leg-curl-machine'], array['сгибание ног лежа','lying leg curl'], 'Исходное положение: лягте в тренажёр, валик над пятками, таз прижат. Выполнение: согните колени и плавно опустите валик. Контроль: таз не поднимается. Ошибки: прогибать поясницу, дёргать вес и сокращать обратную фазу.'),
  ('seated-leg-curl', 'Сгибание ног сидя в тренажёре', 'reps', 'hamstrings', array['calves'], array['leg-curl-machine'], array['сгибание ног сидя','seated leg curl'], 'Исходное положение: сядьте, зафиксируйте бёдра и валик над голенями. Выполнение: согните колени и медленно верните валик. Контроль: спина остаётся на опоре. Ошибки: отрывать таз, делать рывки и ставить слишком большой вес.'),
  ('romanian-deadlift', 'Румынская тяга со штангой', 'reps', 'hamstrings', array['glutes','lower-back'], array['barbell'], array['румынская тяга','RDL','romanian deadlift'], 'Исходное положение: держите штангу у бёдер, колени слегка согнуты. Выполнение: отведите таз назад, опустите гриф вдоль ног и вернитесь. Контроль: спина нейтральна, гриф близко к телу. Ошибки: округлять спину, приседать вместо наклона и опускать гриф далеко от ног.'),
  ('barbell-hip-thrust', 'Ягодичный мост со штангой', 'reps', 'glutes', array['hamstrings','core'], array['barbell','bench'], array['хип траст','barbell hip thrust'], 'Исходное положение: верх спины на скамье, штанга на тазу, стопы под коленями. Выполнение: поднимите таз до прямой линии корпуса и опустите. Контроль: подбородок слегка опущен, рёбра не выпячиваются. Ошибки: переразгибать поясницу, толкать носками и отрывать стопы.'),
  ('glute-bridge', 'Ягодичный мост с собственным весом', 'reps', 'glutes', array['hamstrings','core'], array['bodyweight'], array['ягодичный мост','glute bridge'], 'Исходное положение: лягте на спину, согните колени, стопы поставьте на пол. Выполнение: поднимите таз и плавно опустите. Контроль: давите всей стопой, держите рёбра собранными. Ошибки: прогибать поясницу, разводить колени и поднимать таз рывком.'),
  ('cable-glute-kickback', 'Отведение ноги назад на нижнем блоке', 'reps', 'glutes', array['hamstrings'], array['cable-machine'], array['кикбэк','cable kickback'], 'Исходное положение: закрепите манжету на лодыжке, возьмитесь за опору. Выполнение: отведите прямую ногу назад и верните. Контроль: таз остаётся ровным, корпус не качается. Ошибки: разворачивать таз, прогибать поясницу и делать мах.'),
  ('hip-abduction-machine', 'Отведение бёдер в тренажёре', 'reps', 'abductors', array['glutes'], array['hip-abductor-machine'], array['разведение ног в тренажере','hip abduction machine'], 'Исходное положение: сядьте ровно, колени на подушках тренажёра. Выполнение: разведите бёдра и медленно верните. Контроль: таз и спина остаются на опоре. Ошибки: раскачиваться, бросать вес и сокращать амплитуду.'),
  ('hip-adduction-machine', 'Приведение бёдер в тренажёре', 'reps', 'adductors', array[]::text[], array['hip-abductor-machine'], array['сведение ног в тренажере','hip adduction machine'], 'Исходное положение: сядьте ровно, ноги разведены на подушках тренажёра. Выполнение: сведите бёдра и плавно верните. Контроль: корпус стабилен, движение без рывка. Ошибки: помогать спиной, бросать вес и закрывать колени резко.'),
  ('standing-calf-raise', 'Подъёмы на носки стоя', 'reps', 'calves', array[]::text[], array['bodyweight'], array['подъемы на носки','standing calf raise'], 'Исходное положение: встаньте ровно, передняя часть стоп на устойчивой опоре при необходимости. Выполнение: поднимитесь на носки и медленно опустите пятки. Контроль: колени мягкие, движение через голеностоп. Ошибки: пружинить, заваливать стопы и сокращать нижнюю фазу.'),
  ('seated-calf-raise', 'Подъёмы на носки сидя', 'reps', 'calves', array[]::text[], array['calf-raise-machine'], array['икры сидя','seated calf raise'], 'Исходное положение: сядьте в тренажёр, передняя часть стоп на платформе. Выполнение: поднимите пятки и опустите ниже уровня платформы под контролем. Контроль: колени остаются неподвижны. Ошибки: пружинить, отрывать носки и использовать слишком короткую амплитуду.'),
  ('sumo-deadlift', 'Становая тяга сумо', 'reps', 'glutes', array['quadriceps','hamstrings','back'], array['barbell'], array['сумо тяга','sumo deadlift'], 'Исходное положение: поставьте стопы широко, носки слегка наружу, возьмитесь за гриф внутри колен. Выполнение: выпрямитесь, толкая пол ногами. Контроль: спина нейтральна, колени идут по носкам. Ошибки: округлять поясницу, уводить гриф от тела и сводить колени.'),
  ('kettlebell-deadlift', 'Становая тяга с гирей', 'reps', 'glutes', array['hamstrings','back'], array['kettlebell'], array['тяга с гирей','kettlebell deadlift'], 'Исходное положение: гиря между стопами, таз отведён назад, спина нейтральна. Выполнение: выпрямитесь, держа гирю близко к телу. Контроль: движение начинается ногами и тазом. Ошибки: округлять спину, приседать слишком глубоко и тянуть гирю руками.'),
  ('single-leg-romanian-deadlift', 'Румынская тяга на одной ноге', 'reps', 'hamstrings', array['glutes','core'], array['dumbbells'], array['одноногая румынская тяга','single leg RDL'], 'Исходное положение: перенесите вес на одну ногу, гантель держите в противоположной руке. Выполнение: отведите свободную ногу назад и вернитесь. Контроль: таз остаётся ровным, опорная стопа стабильна. Ошибки: разворачивать таз, округлять спину и терять равновесие рывком.'),
  ('nordic-hamstring-curl', 'Сгибание ног нордик', 'reps', 'hamstrings', array['glutes','core'], array['bodyweight'], array['нордические сгибания','nordic curl'], 'Исходное положение: закрепите лодыжки, встаньте на колени, корпус прямой. Выполнение: медленно наклонитесь вперёд и вернитесь с доступной помощью рук. Контроль: таз не сгибается, шея нейтральна. Ошибки: падать без контроля, прогибаться в пояснице и делать движение рывком.'),

  -- Пресс и корпус (14)
  ('forearm-plank', 'Планка на предплечьях', 'duration', 'core', array['glutes','shoulders'], array['bodyweight'], array['планка','plank'], 'Исходное положение: упритесь предплечьями и носками в пол, тело в прямой линии. Выполнение: удерживайте положение заданное время. Контроль: напрягайте корпус и ягодицы, дышите спокойно. Ошибки: провисать поясницей, поднимать таз и задерживать дыхание.'),
  ('side-plank', 'Боковая планка', 'duration', 'obliques', array['core','shoulders'], array['bodyweight'], array['боковая планка','side plank'], 'Исходное положение: упритесь предплечьем в пол, ноги вытянуты одна над другой. Выполнение: поднимите таз и удерживайте прямую линию. Контроль: плечо над локтем, корпус не разворачивается. Ошибки: провисать тазом, заваливать плечо и задерживать дыхание.'),
  ('dead-bug', 'Мёртвый жук', 'reps', 'core', array['hip-flexors'], array['bodyweight'], array['dead bug','мертвый жук'], 'Исходное положение: лягте на спину, руки вверх, колени согнуты под прямым углом. Выполнение: опускайте противоположные руку и ногу, затем верните. Контроль: поясница мягко прижата к полу. Ошибки: прогибаться, спешить и терять координацию.'),
  ('bird-dog', 'Птица-собака', 'reps', 'core', array['glutes','shoulders'], array['bodyweight'], array['bird dog','птица собака'], 'Исходное положение: встаньте на четвереньки, ладони под плечами. Выполнение: вытяните противоположные руку и ногу, затем смените сторону. Контроль: таз остаётся ровным, шея нейтральна. Ошибки: прогибать поясницу, разворачивать таз и делать махи.'),
  ('crunch', 'Скручивания лёжа', 'reps', 'core', array[]::text[], array['bodyweight'], array['скручивания','crunch'], 'Исходное положение: лягте на спину, колени согнуты, руки у висков или на груди. Выполнение: приподнимите лопатки и плавно опуститесь. Контроль: подбородок не тянется к груди. Ошибки: тянуть шею руками, делать рывок и отрывать поясницу.'),
  ('cable-crunch', 'Скручивания на верхнем блоке', 'reps', 'core', array['obliques'], array['cable-machine'], array['скручивания на блоке','cable crunch'], 'Исходное положение: встаньте на колени лицом к верхнему блоку, канат у лба. Выполнение: скрутите корпус вниз и вернитесь. Контроль: таз остаётся над коленями, движение в корпусе. Ошибки: тянуть руками, садиться тазом назад и округлять шею.'),
  ('hanging-knee-raise', 'Подъём коленей в висе', 'reps', 'hip-flexors', array['core','forearms'], array['pull-up-bar'], array['подъем коленей в висе','hanging knee raise'], 'Исходное положение: повисните на турнике с активными плечами. Выполнение: подтяните колени к груди и медленно опустите. Контроль: избегайте раскачки, таз подкручивайте. Ошибки: махать ногами, тянуть шеей и резко опускать колени.'),
  ('hanging-leg-raise', 'Подъём прямых ног в висе', 'reps', 'hip-flexors', array['core','forearms'], array['pull-up-bar'], array['подъем ног в висе','hanging leg raise'], 'Исходное положение: повисните на турнике, ноги вместе. Выполнение: поднимите прямые ноги до доступной высоты и опустите. Контроль: плечи активны, корпус без раскачки. Ошибки: делать мах, прогибаться и терять контроль внизу.'),
  ('lying-leg-raise', 'Подъём прямых ног лёжа', 'reps', 'hip-flexors', array['core'], array['bodyweight'], array['подъем ног лежа','lying leg raise'], 'Исходное положение: лягте на спину, руки вдоль тела или под тазом. Выполнение: поднимите ноги и медленно опустите до доступной высоты. Контроль: поясница остаётся на полу. Ошибки: прогибать поясницу, бросать ноги и поднимать голову.'),
  ('reverse-crunch', 'Обратные скручивания', 'reps', 'core', array['hip-flexors'], array['bodyweight'], array['обратные скручивания','reverse crunch'], 'Исходное положение: лягте на спину, колени согнуты и подняты. Выполнение: подкрутите таз, направляя колени к груди, затем опустите. Контроль: движение начинается с таза. Ошибки: раскачивать ногами, тянуть шею и бросать таз на пол.'),
  ('russian-twist', 'Русские скручивания', 'reps', 'obliques', array['core','hip-flexors'], array['medicine-ball'], array['русский твист','russian twist'], 'Исходное положение: сядьте, слегка отклоните корпус, медбол держите перед собой. Выполнение: поворачивайте грудную клетку по сторонам. Контроль: спина длинная, движение не только руками. Ошибки: округляться, раскачивать ногами и делать быстрые рывки.'),
  ('pallof-press', 'Жим Паллофа', 'reps', 'obliques', array['core','shoulders'], array['cable-machine'], array['pallof press','паллоф'], 'Исходное положение: встаньте боком к блоку, рукоять у груди. Выполнение: выжмите руки перед собой и верните, не позволяя корпусу вращаться. Контроль: таз и рёбра направлены вперёд. Ошибки: разворачиваться к блоку, задерживать дыхание и раскачиваться.'),
  ('ab-wheel-rollout', 'Прокатка ролика для пресса', 'reps', 'core', array['shoulders','hip-flexors'], array['ab-wheel'], array['ролик для пресса','ab wheel rollout'], 'Исходное положение: встаньте на колени, руки на ролике под плечами. Выполнение: прокатите ролик вперёд до доступной амплитуды и верните. Контроль: держите таз подкрученным и корпус жёстким. Ошибки: провисать поясницей, уходить слишком далеко и делать рывок.'),
  ('mountain-climber', 'Альпинист', 'duration', 'core', array['hip-flexors','shoulders'], array['bodyweight'], array['скалолаз','mountain climber'], 'Исходное положение: примите упор лёжа, ладони под плечами. Выполнение: поочерёдно подтягивайте колени к груди в выбранном темпе. Контроль: таз остаётся на одной высоте. Ошибки: поднимать таз, проваливаться в плечах и терять ритм.'),

  -- Функциональные (12)
  ('kettlebell-swing', 'Махи гирей', 'reps', 'full-body', array['glutes','hamstrings','core'], array['kettlebell'], array['свинг','kettlebell swing'], 'Исходное положение: встаньте над гирей, таз отведите назад, спина нейтральна. Выполнение: мощно разогните таз и дайте гире подняться до уровня груди. Контроль: руки направляют гирю, корпус собран. Ошибки: приседать вместо наклона, тянуть гирю плечами и прогибаться в пояснице.'),
  ('kettlebell-clean-and-press', 'Взятие гири на грудь и жим', 'reps', 'full-body', array['shoulders','glutes','core'], array['kettlebell'], array['clean and press','взятие и жим гири'], 'Исходное положение: гиря перед стопами, корпус собран. Выполнение: подведите гирю к плечу через таз и выжмите над головой. Контроль: ловите гирю мягко у предплечья, корпус стабилен. Ошибки: бить гирей по запястью, тянуть рукой и прогибать поясницу.'),
  ('dumbbell-thruster', 'Трастеры с гантелями', 'reps', 'full-body', array['quadriceps','shoulders','core'], array['dumbbells'], array['трастер','dumbbell thruster'], 'Исходное положение: гантели у плеч, стопы на ширине плеч. Выполнение: встаньте из приседа и одним движением выжмите гантели вверх. Контроль: колени идут по носкам, корпус собран. Ошибки: терять глубину приседа, прогибать поясницу и ловить гантели рывком.'),
  ('burpee', 'Бёрпи', 'reps', 'full-body', array['chest','quadriceps','core'], array['bodyweight'], array['берпи','burpee'], 'Исходное положение: встаньте ровно, стопы устойчиво. Выполнение: опуститесь в упор, вернитесь в стойку и выполните лёгкий прыжок по готовности. Контроль: приземляйтесь мягко, корпус собран. Ошибки: провисать в упоре, жёстко приземляться и терять технику ради темпа.'),
  ('farmer-carry', 'Прогулка фермера с гантелями', 'duration', 'full-body', array['forearms','core','shoulders'], array['dumbbells'], array['фермерская прогулка','farmer carry'], 'Исходное положение: возьмите тяжести по бокам, выпрямитесь. Выполнение: идите ровными короткими шагами заданное время. Контроль: плечи опущены, корпус не наклоняется. Ошибки: сутулиться, раскачивать гантели и задерживать дыхание.'),
  ('suitcase-carry', 'Перенос веса в одной руке', 'duration', 'full-body', array['obliques','forearms'], array['dumbbells'], array['suitcase carry','чемоданная прогулка'], 'Исходное положение: возьмите гантель в одну руку, стойте ровно. Выполнение: идите заданное время и затем смените сторону. Контроль: не наклоняйтесь к весу, шаги спокойные. Ошибки: заваливать корпус, поднимать плечо и раскачивать гантель.'),
  ('sled-push', 'Толкание саней', 'distance', 'full-body', array['quadriceps','glutes','core'], array['sled'], array['пуш саней','sled push'], 'Исходное положение: возьмитесь за стойки саней, корпус наклонён и жёсткий. Выполнение: толкайте сани короткими шагами на заданную дистанцию. Контроль: спина нейтральна, стопы толкают пол. Ошибки: округляться, делать слишком длинные шаги и терять контроль скорости.'),
  ('medicine-ball-slam', 'Броски медбола в пол', 'reps', 'full-body', array['shoulders','core','glutes'], array['medicine-ball'], array['слэмы с медболом','medicine ball slam'], 'Исходное положение: держите медбол перед собой, стопы устойчиво. Выполнение: поднимите мяч над головой и направьте его в пол, затем подберите. Контроль: сгибайте колени при подборе, держите корпус собранным. Ошибки: округлять спину, бросать рядом со стопами и терять устойчивость.'),
  ('box-jump', 'Запрыгивания на тумбу', 'reps', 'full-body', array['quadriceps','glutes','calves'], array['plyo-box'], array['прыжок на тумбу','box jump'], 'Исходное положение: встаньте перед устойчивой тумбой на комфортном расстоянии. Выполнение: мягко запрыгните всей стопой и полностью выпрямитесь. Контроль: приземляйтесь тихо, колени идут по носкам. Ошибки: выбирать слишком высокую тумбу, приземляться на носки и терять баланс.'),
  ('battle-rope-waves', 'Волны канатами', 'duration', 'full-body', array['shoulders','core','forearms'], array['battle-ropes'], array['канаты','battle rope waves'], 'Исходное положение: встаньте в устойчивую полуприседную стойку, по канату в каждой руке. Выполнение: создавайте чередующиеся волны заданное время. Контроль: корпус стабилен, плечи опущены. Ошибки: выпрямлять колени, зажимать шею и терять ритм.'),
  ('bear-crawl', 'Медвежья ходьба', 'distance', 'full-body', array['shoulders','core','quadriceps'], array['bodyweight'], array['bear crawl','медвежья походка'], 'Исходное положение: встаньте на четвереньки, колени чуть над полом. Выполнение: двигайтесь вперёд противоположными рукой и ногой на заданную дистанцию. Контроль: спина ровная, шаги короткие. Ошибки: поднимать таз, провисать в пояснице и спешить.'),
  ('turkish-get-up', 'Турецкий подъём с гирей', 'reps', 'full-body', array['shoulders','core','glutes'], array['kettlebell'], array['турецкий подъем','turkish get-up'], 'Исходное положение: лягте на спину, гиря выжата в одной руке. Выполнение: поэтапно перейдите в стойку и вернитесь тем же путём. Контроль: всё время смотрите на гирю и двигайтесь медленно. Ошибки: пропускать этапы, терять вертикаль руки и спешить.'),

  -- Кардио (17)
  ('treadmill-walk', 'Ходьба на беговой дорожке', 'duration', 'cardio', array['quadriceps','calves'], array['treadmill'], array['ходьба дорожка','treadmill walk'], 'Исходное положение: встаньте по центру дорожки, начните с комфортной скорости. Выполнение: идите заданное время ровным шагом. Контроль: смотрите вперёд, руки двигаются естественно. Ошибки: держаться за поручни без необходимости, смотреть вниз и резко менять скорость.'),
  ('treadmill-run', 'Бег на беговой дорожке', 'duration', 'cardio', array['quadriceps','calves','glutes'], array['treadmill'], array['бег дорожка','treadmill run'], 'Исходное положение: начните с разминки на комфортной скорости. Выполнение: бегите заданное время ровным ритмом. Контроль: приземляйтесь мягко, смотрите вперёд. Ошибки: держаться за поручни, увеличивать скорость резко и делать слишком длинный шаг.'),
