  ('air-bike-interval', 'Интервалы на аэробайке', 'duration', 'cardio', array['quadriceps','shoulders','core'], array['air-bike'], array['аэробайк','air bike'], 'Исходное положение: настройте сиденье, стопы закрепите, руки на рукоятях. Выполнение: работайте заданные интервалы ногами и руками. Контроль: корпус устойчив, дыхание ритмично. Ошибки: сутулиться, резко стартовать на максимуме и терять технику при усталости.'),
  ('ski-ergometer', 'Лыжный тренажёр', 'duration', 'cardio', array['back','core','triceps'], array['ski-ergometer'], array['ски эрг','ski erg'], 'Исходное положение: встаньте перед тренажёром, рукояти над головой. Выполнение: тяните рукояти вниз через корпус и плавно верните. Контроль: наклон идёт из тазобедренных суставов, спина нейтральна. Ошибки: округлять поясницу, тянуть только руками и делать рывки.'),
  ('freestyle-swimming', 'Плавание кролем', 'duration', 'cardio', array['back','shoulders','core'], array['swimming-pool'], array['кроль','freestyle swimming'], 'Исходное положение: оттолкнитесь от бортика и вытянитесь в воде. Выполнение: чередуйте гребки и работу ног в комфортном темпе. Контроль: поворачивайте корпус для вдоха, сохраняйте вытяжение. Ошибки: поднимать голову вперёд, задерживать дыхание и пересекать руками линию тела.'),
  ('outdoor-run', 'Бег на улице', 'distance', 'cardio', array['quadriceps','calves','glutes'], array['outdoor'], array['бег','running','outdoor run'], 'Исходное положение: начните с комфортного темпа на безопасном маршруте. Выполнение: бегите заданную дистанцию ровным ритмом. Контроль: смотрите вперёд, приземляйтесь мягко под корпусом. Ошибки: резко ускоряться, смотреть под ноги постоянно и делать слишком длинный шаг.'),
  ('outdoor-walk', 'Ходьба на улице', 'distance', 'cardio', array['quadriceps','calves'], array['outdoor'], array['ходьба','walking','outdoor walk'], 'Исходное положение: выберите безопасный маршрут и удобную обувь. Выполнение: идите заданную дистанцию активным, но контролируемым шагом. Контроль: держите корпус ровно, руки двигаются свободно. Ошибки: сутулиться, смотреть в телефон на ходу и резко менять темп.'),
  ('outdoor-cycling', 'Велосипед на улице', 'distance', 'cardio', array['quadriceps','glutes','calves'], array['outdoor'], array['велосипед','outdoor cycling'], 'Исходное положение: настройте велосипед и проверьте безопасный маршрут. Выполнение: крутите педали заданную дистанцию в комфортном темпе. Контроль: плечи расслаблены, колени идут по линии стоп. Ошибки: сутулиться, резко переключать передачу и игнорировать дорожную обстановку.'),
  ('shadow-boxing', 'Бой с тенью', 'duration', 'cardio', array['shoulders','core','quadriceps'], array['bodyweight'], array['бокс с тенью','shadow boxing'], 'Исходное положение: встаньте в устойчивую боксерскую стойку, руки у лица. Выполнение: наносите лёгкие контролируемые серии в воздух заданное время. Контроль: вращайте корпус и возвращайте руки к защите. Ошибки: полностью выпрямлять локти рывком, задерживать дыхание и терять стойку.'),
  ('marching-high-knees', 'Бег с высоким подниманием коленей', 'duration', 'cardio', array['hip-flexors','quadriceps','core'], array['bodyweight'], array['высокие колени','high knees'], 'Исходное положение: встаньте ровно, руки согните как при беге. Выполнение: поочерёдно поднимайте колени в выбранном темпе. Контроль: корпус вертикален, приземление мягкое. Ошибки: заваливаться назад, шумно приземляться и терять ритм.'),
  ('low-impact-jacks', 'Шаговые прыжки джек', 'duration', 'cardio', array['shoulders','quadriceps','core'], array['bodyweight'], array['джампинг джек','low impact jacks'], 'Исходное положение: встаньте ровно, руки по бокам. Выполнение: поочерёдно шагайте в сторону и поднимайте руки над головой. Контроль: движения мягкие и ритмичные. Ошибки: сутулиться, поднимать плечи и терять устойчивую постановку стоп.'),
  ('cardio-step-touch', 'Степ-тач', 'duration', 'cardio', array['quadriceps','calves'], array['bodyweight'], array['шаги в сторону','step touch'], 'Исходное положение: встаньте ровно, стопы на ширине таза. Выполнение: шагайте в сторону с приставлением второй стопы заданное время. Контроль: колени мягкие, корпус вертикален. Ошибки: скрещивать ноги, делать рывки и переносить вес на носки.')
;

do $$
begin
  if (select count(*) from flux_catalog_seed) <> 125 then
    raise exception 'Initial catalog seed must contain exactly 125 exercises';
  end if;

  if exists (
    select 1
    from flux_catalog_seed
    where slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$'
       or name <> btrim(name)
       or measurement_type not in ('reps', 'duration', 'distance')
       or btrim(technique_description) = ''
       or position('Исходное положение:' in technique_description) = 0
       or position('Выполнение:' in technique_description) = 0
       or position('Контроль:' in technique_description) = 0
       or position('Ошибки:' in technique_description) = 0
  ) then
    raise exception 'Initial catalog seed contains invalid exercise content';
  end if;

  if exists (
    select 1
    from flux_catalog_seed seed
    left join public.muscle_groups primary_group on primary_group.slug = seed.primary_muscle_slug
    where primary_group.id is null
  ) or exists (
    select 1
    from flux_catalog_seed seed
    cross join lateral unnest(seed.secondary_muscle_slugs) as secondary_slug(slug)
    left join public.muscle_groups secondary_group on secondary_group.slug = secondary_slug.slug
    where secondary_group.id is null
  ) or exists (
    select 1
    from flux_catalog_seed seed
    cross join lateral unnest(seed.equipment_slugs) as equipment_slug(slug)
    left join public.equipment equipment_row on equipment_row.slug = equipment_slug.slug
    where equipment_row.id is null
  ) then
    raise exception 'Initial catalog seed references an unknown lookup slug';
  end if;
end;
$$;

with inserted as (
  insert into public.exercise_catalog (
    slug, name, normalized_name, measurement_type, technique_description,
    primary_muscle_group_id, publication_status
  )
  select
    seed.slug,
    seed.name,
    lower(seed.name),
    seed.measurement_type,
    seed.technique_description,
    muscle_group.id,
    'published'
  from flux_catalog_seed seed
  join public.muscle_groups muscle_group on muscle_group.slug = seed.primary_muscle_slug
  on conflict (slug) do nothing
  returning id, slug
)
insert into flux_catalog_inserted (id, slug)
select id, slug from inserted;

insert into public.exercise_catalog_muscle_groups (catalog_exercise_id, muscle_group_id, role)
select
  inserted.id,
  muscle_group.id,
  case when muscle_group.slug = seed.primary_muscle_slug then 'primary' else 'secondary' end
from flux_catalog_inserted inserted
join flux_catalog_seed seed on seed.slug = inserted.slug
cross join lateral unnest(array_prepend(seed.primary_muscle_slug, seed.secondary_muscle_slugs)) as muscle_slug(slug)
join public.muscle_groups muscle_group on muscle_group.slug = muscle_slug.slug;

insert into public.exercise_catalog_equipment (catalog_exercise_id, equipment_id)
select inserted.id, equipment_row.id
from flux_catalog_inserted inserted
join flux_catalog_seed seed on seed.slug = inserted.slug
cross join lateral unnest(seed.equipment_slugs) as equipment_slug(slug)
join public.equipment equipment_row on equipment_row.slug = equipment_slug.slug;

insert into public.exercise_catalog_aliases (catalog_exercise_id, alias, normalized_alias)
select inserted.id, alias.alias, lower(alias.alias)
from flux_catalog_inserted inserted
join flux_catalog_seed seed on seed.slug = inserted.slug
cross join lateral unnest(seed.aliases) as alias(alias);

do $$
begin
  if exists (
    select 1
    from flux_catalog_seed seed
    left join public.exercise_catalog catalog on catalog.slug = seed.slug
    where catalog.id is null
  ) then
    raise exception 'Initial catalog seed did not create every missing catalog row';
  end if;

  if exists (
    select 1
    from flux_catalog_inserted inserted
    join flux_catalog_seed seed on seed.slug = inserted.slug
    where not exists (
      select 1
      from public.exercise_catalog_muscle_groups relation
      join public.muscle_groups group_row on group_row.id = relation.muscle_group_id
      where relation.catalog_exercise_id = inserted.id
        and relation.role = 'primary'
        and group_row.slug = seed.primary_muscle_slug
    )
  ) then
    raise exception 'Inserted catalog row is missing its primary muscle relation';
  end if;
end;
$$;

commit;
